// ***************
// Filename: baud_nco_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of baud_nco: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to baud_nco's logic on named ports, its
//   status comes back on input ports. Baud-rate / sine NCO: control,
//   frequency control word, phase offset, gain, status, tick counter.
//   Generated by ip/scripts/regmap_gen.py from baud_nco_regs.json: edit the
//   JSON and regenerate (the IP_VERSION / IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "BNCO" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 CTRL        CMD  control (reads [2] as 0)
//                       [0] EN: 1: NCO running (reset 1)
//                       [1] STREAM_EN: 1: samples on the AXI-Stream master
//                       [2] PHASE_RST: write 1: phase back to 0 (self
//                         clearing)
//     0x14 FCW         RW   frequency control word: phase step per clock
//                       (2^PHASE_W = one turn), reset FCW_RST
//     0x18 PHASE_OFF   RW   phase offset of the sine output, reset 0x0
//     0x1C GAIN        RW   sine amplitude, reset 0x7FFF
//     0x20 STATUS      RO   status
//                       [0] EN: NCO running
//                       [1] TVALID: a sample is offered on the stream
//     0x24 TICK_COUNT  CMD  baud ticks counted; a write clears it
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - aclk.
//   Reset - synchronous active low aresetn. Latency - 2 clocks per write and
//   read.
// Date: 2026-10-12
module baud_nco_regs #(
  parameter logic [31:0] FCW_RST = 32'd0  // FCW at reset (BAUD * OSR * 2^PHASE_W / CLK_HZ)
) (
  input  logic          aclk,            // clock
  input  logic          aresetn,         // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  input  logic [7:0]    s_axil_awaddr,   // AXI4-Lite
  input  logic          s_axil_awvalid,
  output logic          s_axil_awready,
  input  logic [31:0]   s_axil_wdata,
  input  logic [3:0]    s_axil_wstrb,
  input  logic          s_axil_wvalid,
  output logic          s_axil_wready,
  output logic [1:0]    s_axil_bresp,
  output logic          s_axil_bvalid,
  input  logic          s_axil_bready,
  input  logic [7:0]    s_axil_araddr,
  input  logic          s_axil_arvalid,
  output logic          s_axil_arready,
  output logic [31:0]   s_axil_rdata,
  output logic [1:0]    s_axil_rresp,
  output logic          s_axil_rvalid,
  input  logic          s_axil_rready,
  input  logic [3-1:0]  ctrl_i,          // CTRL (CMD): value read
  output logic [3-1:0]  ctrl_o,          // CTRL (CMD): data written
  output logic          ctrl_wr_o,       // CTRL: one-clock pulse at every software write
  output logic [32-1:0] fcw_o,           // FCW (RW): register value
  output logic          fcw_wr_o,        // FCW: one-clock pulse at every software write
  output logic [16-1:0] phase_off_o,     // PHASE_OFF (RW): register value
  output logic          phase_off_wr_o,  // PHASE_OFF: one-clock pulse at every software write
  output logic [15-1:0] gain_o,          // GAIN (RW): register value
  output logic          gain_wr_o,       // GAIN: one-clock pulse at every software write
  input  logic [2-1:0]  status_i,        // STATUS (RO): value read
  input  logic [32-1:0] tick_count_i,    // TICK_COUNT (CMD): value read
  output logic [32-1:0] tick_count_o,    // TICK_COUNT (CMD): data written
  output logic          tick_count_wr_o  // TICK_COUNT: one-clock pulse at every software write
);
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "BNCO";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_CTRL = 8'h10;
  localparam logic [7:0] A_FCW = 8'h14;
  localparam logic [7:0] A_PHASE_OFF = 8'h18;
  localparam logic [7:0] A_GAIN = 8'h1C;
  localparam logic [7:0] A_STATUS = 8'h20;
  localparam logic [7:0] A_TICK_COUNT = 8'h24;
  localparam int MAP_WORDS = 10;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(aclk),
    .aresetn(aresetn),
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .wr_en_o(wr_en),
    .wr_addr_o(wr_addr),
    .wr_data_o(wr_data),
    .wr_strb_o(wr_strb),
    .wr_err_i(wr_err_q),
    .rd_en_o(rd_en),
    .rd_addr_o(rd_addr),
    .rd_data_i(rd_data),
    .rd_valid_i(1'b1),
    .rd_err_i(1'b0)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] ctrl_q;
  logic [31:0] fcw_q;
  logic [31:0] phase_off_q;
  logic [31:0] gain_q;
  logic [31:0] tick_count_q;
  always_ff @(posedge aclk) begin
    if (!aresetn) begin
      ctrl_q <= '0;
      ctrl_wr_o <= 1'b0;
      fcw_q <= 32'(FCW_RST);
      fcw_wr_o <= 1'b0;
      phase_off_q <= 32'h0;
      phase_off_wr_o <= 1'b0;
      gain_q <= 32'h7FFF;
      gain_wr_o <= 1'b0;
      tick_count_q <= '0;
      tick_count_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_STATUS);   // writes to read-only words: SLVERR
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        fcw_wr_o <= wr_en && wa == A_FCW;
        if (wr_en && wa == A_FCW) fcw_q <= (fcw_q & ~wmask) | (wr_data & wmask);
      end
      begin
        phase_off_wr_o <= wr_en && wa == A_PHASE_OFF;
        if (wr_en && wa == A_PHASE_OFF) phase_off_q <= (phase_off_q & ~wmask) | (wr_data & wmask);
      end
      begin
        gain_wr_o <= wr_en && wa == A_GAIN;
        if (wr_en && wa == A_GAIN) gain_q <= (gain_q & ~wmask) | (wr_data & wmask);
      end
      begin
        tick_count_wr_o <= wr_en && wa == A_TICK_COUNT;
        if (wr_en && wa == A_TICK_COUNT) tick_count_q <= (tick_count_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign ctrl_o = ctrl_q[3-1:0];
  assign fcw_o = fcw_q[32-1:0];
  assign phase_off_o = phase_off_q[16-1:0];
  assign gain_o = gain_q[15-1:0];
  assign tick_count_o = tick_count_q[32-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge aclk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_CTRL: rd_data = 32'(ctrl_i);
      A_FCW: rd_data = fcw_q;
      A_PHASE_OFF: rd_data = phase_off_q;
      A_GAIN: rd_data = gain_q;
      A_STATUS: rd_data = 32'(status_i);
      A_TICK_COUNT: rd_data = 32'(tick_count_i);
      default: begin
      end
    endcase
  end
endmodule
